## Problem 4 — transfer, and proving it happened

Edit `ex4/solution.ts`. Implement:

```ts
export function scaleInWorker(
  bytes: Uint8Array,
  factor: number,
): Promise<{ result: Uint8Array; sourceDetached: boolean }>
```

Transfer the input's `ArrayBuffer` into a worker (do not clone it), have the
worker multiply every byte by `factor` **in place** (clamped at 255), transfer
the buffer back, and resolve with a `Uint8Array` view over the returned
buffer.

`sourceDetached` reports whether the caller's original buffer was detached by
the transfer — for a real transfer it is `true`, and `bytes.byteLength` is `0`
afterwards.

```ts
const input = new Uint8Array(new ArrayBuffer(4));
input.set([1, 2, 3, 200]);
await scaleInWorker(input, 2);
// { result: Uint8Array [2, 4, 6, 255], sourceDetached: true }
// input.byteLength === 0
```

```
uv run dojo test node v3nc01_worker_threads ex4
```

references.solution.ts:
// v3nc01_worker_threads / ex4 - reference solution (author only, used by `dojo verify`).
import { Worker } from "node:worker_threads";

const SOURCE = `
const { parentPort } = require("node:worker_threads");
parentPort.on("message", ({ buffer, factor }) => {
  const view = new Uint8Array(buffer);
  for (let i = 0; i < view.length; i++) view[i] = Math.min(255, view[i] * factor);
  parentPort.postMessage({ buffer: view.buffer }, [view.buffer]);
});
`;

export function scaleInWorker(
  bytes: Uint8Array,
  factor: number,
): Promise<{ result: Uint8Array; sourceDetached: boolean }> {
  // A view that does not own its whole ArrayBuffer (every pooled Buffer, for
  // instance) is not ours to detach: copy instead, and say so in the result.
  const owned = bytes.byteOffset === 0 && bytes.byteLength === bytes.buffer.byteLength;
  const buffer = owned ? bytes.buffer : bytes.slice().buffer;

  return new Promise((resolve, reject) => {
    const worker = new Worker(SOURCE, { eval: true });
    const fail = (error: Error): void => {
      void worker.terminate();
      reject(error);
    };

    worker.once("error", fail);
    worker.once("message", ({ buffer: back }: { buffer: ArrayBuffer }) => {
      void worker.terminate();
      resolve({
        result: new Uint8Array(back),
        // A detached buffer reports zero length; that is the whole proof.
        sourceDetached: owned && bytes.byteLength === 0,
      });
    });

    worker.postMessage({ buffer, factor }, [buffer]);
  });
}

// v3nc01_worker_threads / ex5 - reference solution (author only, used by `dojo verify`).
import { Worker } from "node:worker_threads";

const SOURCE = `
const { workerData } = require("node:worker_threads");
const { shared, perWorker } = workerData;
// Real code would accumulate locally and do one Atomics.add at the end; the
// per-iteration version is here because it is the one that must stay correct.
for (let i = 0; i < perWorker; i++) Atomics.add(shared, 0, 1);
`;

export async function countInParallel(workers: number, perWorker: number): Promise<number> {
  // One SharedArrayBuffer, one Int32 slot, shared by reference with every
  // thread - this is the one value in the sector that is not copied.
  const shared = new Int32Array(new SharedArrayBuffer(Int32Array.BYTES_PER_ELEMENT));

  const threads = Array.from({ length: workers }, () =>
    new Worker(SOURCE, { eval: true, workerData: { shared, perWorker } }),
  );

  try {
    await Promise.all(
      threads.map(
        (worker) =>
          new Promise<void>((resolve, reject) => {
            worker.once("error", reject);
            worker.once("exit", (code) =>
              code === 0 ? resolve() : reject(new Error(`counter worker exited with code ${code}`)),
            );
          }),
      ),
    );
  } finally {
    await Promise.all(threads.map((worker) => worker.terminate()));
  }

  // Every writer has exited, so nothing can be in flight - but the atomic read
  // is still the one that is defined to see all of their writes.
  return Atomics.load(shared, 0);
}

