## Problem 6 — a pool, because spawning is not free

Edit `ex6/solution.ts`. Implement a `WorkerPool` class:

```ts
export class WorkerPool {
  constructor(options: { size: number; source: string });
  run<T>(payload: unknown): Promise<T>;
  stats(): { spawned: number; busy: number; queued: number; idle: number };
  close(): Promise<void>;
}
```

Rules:

- at most `size` workers exist at any moment, and `spawned` counts how many
  were ever created — running 20 tasks through a pool of 2 must leave
  `spawned` at 2;
- a worker is created lazily, on the first task that needs one;
- tasks beyond `size` queue in FIFO order and start as workers free up;
- a task that rejects must still return its worker to the pool;
- `close()` waits for in-flight tasks, then terminates every worker; calls to
  `run` after `close` reject.

The worker `source` receives one message per task and posts one reply.

```ts
const pool = new WorkerPool({ size: 2, source: SQUARE_SOURCE });
await Promise.all([1, 2, 3, 4, 5].map((n) => pool.run<number>(n)));  // [1,4,9,16,25]
pool.stats().spawned;   // 2
await pool.close();
```

```
uv run dojo test node v3nc01_worker_threads ex6
```

references.solution.ts:
// v3nc01_worker_threads / ex6 - reference solution (author only, used by `dojo verify`).
import { Worker } from "node:worker_threads";

interface Pending {
  payload: unknown;
  resolve: (value: never) => void;
  reject: (error: unknown) => void;
}

export class WorkerPool {
  readonly #size: number;
  readonly #source: string;
  readonly #idle: Worker[] = [];
  readonly #busy = new Set<Worker>();
  readonly #queue: Pending[] = [];
  #spawned = 0;
  #closing = false;

  constructor(options: { size: number; source: string }) {
    if (options.size < 1) throw new RangeError("pool size must be at least 1");
    this.#size = options.size;
    this.#source = options.source;
  }

  run<T>(payload: unknown): Promise<T> {
    if (this.#closing) return Promise.reject(new Error("pool is closed"));
    const { promise, resolve, reject } = Promise.withResolvers<T>();
    this.#queue.push({ payload, resolve: resolve as (value: never) => void, reject });
    this.#pump();
    return promise;
  }

  stats(): { spawned: number; busy: number; queued: number; idle: number } {
    return {
      spawned: this.#spawned,
      busy: this.#busy.size,
      queued: this.#queue.length,
      idle: this.#idle.length,
    };
  }

  async close(): Promise<void> {
    this.#closing = true;
    // Drain rather than abandon: every promise run() handed out must settle.
    while (this.#queue.length > 0 || this.#busy.size > 0) {
      await new Promise((resolve) => setTimeout(resolve, 1));
    }
    const all = [...this.#idle];
    this.#idle.length = 0;
    await Promise.all(all.map((worker) => worker.terminate()));
  }

  #pump(): void {
    while (this.#queue.length > 0) {
      const worker = this.#acquire();
      if (!worker) return;
      this.#dispatch(worker, this.#queue.shift()!);
    }
  }

  #acquire(): Worker | undefined {
    const idle = this.#idle.pop();
    if (idle) return idle;
    if (this.#busy.size >= this.#size) return undefined;
    this.#spawned += 1;
    return new Worker(this.#source, { eval: true });
  }

  #dispatch(worker: Worker, task: Pending): void {
    this.#busy.add(worker);

    let settled = false;
    // Releasing twice is worse than not releasing: the worker would be handed
    // two tasks at once and their replies would cross.
    const release = (keep: boolean): void => {
      if (settled) return;
      settled = true;
      worker.off("message", onMessage);
      worker.off("error", onError);
      this.#busy.delete(worker);
      if (keep) this.#idle.push(worker);
      else void worker.terminate();
      this.#pump();
    };

    const onMessage = (value: never): void => {
      task.resolve(value);
      release(true);
    };
    // A worker that threw is a worker whose global state is unknown; replace it.
    const onError = (error: Error): void => {
      task.reject(error);
      release(false);
    };

    worker.on("message", onMessage);
    worker.on("error", onError);
    worker.postMessage(task.payload);
  }
}

// v3nc01_worker_threads / ex7 - reference solution (author only, used by `dojo verify`).
import { Worker } from "node:worker_threads";

const SOURCE = `
const { parentPort, workerData } = require("node:worker_threads");
const { flag, iterations } = workerData;
let done = 0;
for (let i = 0; i < iterations; i++) {
  // A mask instead of a modulo: one instruction every iteration, one atomic
  // load every 1024, so cancellation latency is bounded at 1024 items.
  if ((i & 1023) === 0 && Atomics.load(flag, 0) === 1) {
    parentPort.postMessage({ cancelled: true, done });
    return;
  }
  done++;
}
parentPort.postMessage({ cancelled: false, done });
`;

export function runCancellable(
  iterations: number,
  signal: AbortSignal,
  options: { graceMs?: number } = {},
): Promise<{ status: "completed" | "cancelled" | "terminated"; done: number }> {
  const graceMs = options.graceMs ?? 50;
  if (signal.aborted) return Promise.resolve({ status: "cancelled", done: 0 });

  return new Promise((resolve) => {
    const flag = new Int32Array(new SharedArrayBuffer(4));
    const worker = new Worker(SOURCE, { eval: true, workerData: { flag, iterations } });

    let settled = false;
    let grace: NodeJS.Timeout | undefined;
    let lastKnownDone = 0;

    const finish = (status: "completed" | "cancelled" | "terminated", done: number): void => {
      if (settled) return;
      settled = true;
      if (grace) clearTimeout(grace);
      signal.removeEventListener("abort", onAbort);
      worker.off("message", onMessage);
      void worker.terminate();
      resolve({ status, done });
    };

    const onMessage = (msg: { cancelled: boolean; done: number }): void => {
      lastKnownDone = msg.done;
      finish(msg.cancelled ? "cancelled" : "completed", msg.done);
    };

    const onAbort = (): void => {
      // Ask first: the worker gets to stop at a point where its state is sane.
      Atomics.store(flag, 0, 1);
      // Then escalate, because a worker is allowed to ignore you and
      // terminate() is the only thing that does not need its cooperation.
      grace = setTimeout(() => finish("terminated", lastKnownDone), graceMs);
      grace.unref?.();
    };

    worker.on("message", onMessage);
    worker.once("error", () => finish("terminated", lastKnownDone));
    signal.addEventListener("abort", onAbort, { once: true });
  });
}

// v3nc01_worker_threads / ex8 - reference solution (author only, used by `dojo verify`).
import { MessageChannel, Worker, type MessagePort } from "node:worker_threads";

const SOURCE = `
const { parentPort, workerData } = require("node:worker_threads");
const { progress, steps } = workerData;
for (let i = 1; i <= steps; i++) progress.postMessage(i);
progress.close();
parentPort.postMessage({ steps });
`;

export function runWithProgress(
  steps: number,
  onProgress: (completed: number) => void,
): Promise<{ steps: number; updates: number }> {
  return new Promise((resolve, reject) => {
    const channel = new MessageChannel();
    const worker = new Worker(SOURCE, {
      eval: true,
      workerData: { progress: channel.port2 as MessagePort, steps },
      // A MessagePort is transferable; workerData clones unless you say so.
      transferList: [channel.port2],
    });

    let updates = 0;
    let settled = false;
    const finish = (action: () => void): void => {
      if (settled) return;
      settled = true;
      // Close before settling: a queued progress message must never reach the
      // caller after their promise has resolved.
      channel.port1.close();
      void worker.terminate();
      action();
    };

    // Attaching a listener starts the port; an unstarted port buffers silently.
    channel.port1.on("message", (completed: number) => {
      updates += 1;
      onProgress(completed);
    });

    worker.once("message", (result: { steps: number }) =>
      finish(() => resolve({ steps: result.steps, updates })),
    );
    worker.once("error", (error: Error) => finish(() => reject(error)));
  });
}

exercises.prompt:
## Challenge — a pool that can be told to stop

Edit `challenge/solution.ts`. Build a job runner that combines pooling,
transfer and cooperative cancellation:

```ts
export interface JobResult { bytes: Uint8Array; cancelled: boolean; processed: number; }

export function createJobRunner(options: { size: number }): {
  submit(bytes: Uint8Array, signal?: AbortSignal): Promise<JobResult>;
  stats(): { spawned: number; busy: number; queued: number };
  close(): Promise<void>;
};
```

`submit` transfers the caller's buffer to a pooled worker, which increments
every byte (wrapping at 256) while checking a shared cancellation flag every
1024 bytes, and transfers the buffer back. The result reports how many bytes
were processed and whether it stopped early.

Rules:

- at most `size` workers ever exist, and workers are reused across jobs;
- a job whose signal aborts **while queued** never starts and rejects with the
  signal's reason;
- a job whose signal aborts **while running** resolves with
  `cancelled: true` and the partially processed buffer;
- every abort listener is removed when the job settles;
- `close()` rejects pending queued jobs, waits for running ones, then
  terminates the workers.

```
uv run dojo test node v3nc01_worker_threads challenge
```

references.solution.ts:
// v3nc01_worker_threads / challenge - reference solution (author only, used by `dojo verify`).
import { Worker } from "node:worker_threads";

export interface JobResult {
  bytes: Uint8Array;
  cancelled: boolean;
  processed: number;
}

const SOURCE = `
const { parentPort } = require("node:worker_threads");
parentPort.on("message", ({ buffer, flag }) => {
  const view = new Uint8Array(buffer);
  let processed = 0;
  for (let i = 0; i < view.length; i++) {
    if ((i & 1023) === 0 && Atomics.load(flag, 0) === 1) break;
    view[i] = (view[i] + 1) & 0xff;
    processed++;
  }
  // Even a cancelled job hands the memory back: the caller owns those bytes.
  parentPort.postMessage({ buffer: view.buffer, processed, cancelled: processed < view.length }, [view.buffer]);
});
`;

interface Job {
  bytes: Uint8Array;
  signal?: AbortSignal;
  flag: Int32Array;
  state: "queued" | "running" | "settled";
  onAbort?: () => void;
  resolve: (value: JobResult) => void;
  reject: (error: unknown) => void;
}

export function createJobRunner(options: { size: number }) {
  const idle: Worker[] = [];
  const busy = new Set<Worker>();
  const queue: Job[] = [];
  let spawned = 0;
  let closed = false;

  const detach = (job: Job): void => {
    if (job.onAbort && job.signal) job.signal.removeEventListener("abort", job.onAbort);
    job.onAbort = undefined;
    job.state = "settled";
  };

  const pump = (): void => {
    while (queue.length > 0) {
      let worker = idle.pop();
      if (!worker) {
        if (busy.size >= options.size) return;
        spawned += 1;
        worker = new Worker(SOURCE, { eval: true });
      }
      dispatch(worker, queue.shift()!);
    }
  };

  function dispatch(worker: Worker, job: Job): void {
    job.state = "running";
    busy.add(worker);
    // The signal may already have fired while this job sat in the queue and
    // the queue-side handler decided to let it run: store, harmlessly, again.
    if (job.signal?.aborted) Atomics.store(job.flag, 0, 1);

    const onMessage = (msg: { buffer: ArrayBuffer; processed: number; cancelled: boolean }): void => {
      worker.off("message", onMessage);
      worker.off("error", onError);
      busy.delete(worker);
      // The loop returned normally even when cancelled, so this worker's
      // globals are exactly as clean as they were before the job.
      idle.push(worker);
      detach(job);
      job.resolve({
        bytes: new Uint8Array(msg.buffer),
        processed: msg.processed,
        cancelled: msg.cancelled,
      });
      pump();
    };
    const onError = (error: Error): void => {
      worker.off("message", onMessage);
      worker.off("error", onError);
      busy.delete(worker);
      void worker.terminate();
      detach(job);
      job.reject(error);
      pump();
    };

    worker.on("message", onMessage);
    worker.on("error", onError);
    worker.postMessage({ buffer: job.bytes.buffer, flag: job.flag }, [job.bytes.buffer]);
  }

  return {
    submit(bytes: Uint8Array, signal?: AbortSignal): Promise<JobResult> {
      if (closed) return Promise.reject(new Error("runner is closed"));
      if (signal?.aborted) return Promise.reject(signal.reason);

      const { promise, resolve, reject } = Promise.withResolvers<JobResult>();
      const job: Job = {
        bytes,
        signal,
        flag: new Int32Array(new SharedArrayBuffer(4)),
        state: "queued",
        resolve,
        reject,
      };

      if (signal) {
        job.onAbort = (): void => {
          if (job.state === "queued") {
            // Never started: pull it out and reject. No worker is involved.
            queue.splice(queue.indexOf(job), 1);
            detach(job);
            job.reject(signal.reason);
          } else if (job.state === "running") {
            // Running: ask the loop to stop and wait for the buffer to come home.
            Atomics.store(job.flag, 0, 1);
          }
        };
        signal.addEventListener("abort", job.onAbort, { once: true });
      }

      queue.push(job);
      pump();
      return promise;
    },

    stats() {
      return { spawned, busy: busy.size, queued: queue.length };
    },

    async close(): Promise<void> {
      closed = true;
      while (queue.length > 0) {
        const job = queue.shift()!;
        detach(job);
        job.reject(new Error("runner closed before the job started"));
      }
      while (busy.size > 0) await new Promise((r) => setTimeout(r, 1));
      const all = idle.splice(0, idle.length);
      await Promise.all(all.map((worker) => worker.terminate()));
    },
  };
}

