```

references.solution.ts:
// v3nc01_worker_threads / review1 - reference solution (author only, used by `dojo verify`).
import type { Worker } from "node:worker_threads";

export type WorkerOutcome =
  | { kind: "message"; value: unknown }
  | { kind: "error"; error: Error }
  | { kind: "messageerror"; error: Error }
  | { kind: "exit"; code: number };

export function settleWorker(worker: Worker): Promise<WorkerOutcome> {
  return new Promise<WorkerOutcome>((resolve) => {
    let settled = false;

    const cleanup = (): void => {
      worker.off("message", onMessage);
      worker.off("error", onError);
      worker.off("messageerror", onMessageError);
      worker.off("exit", onExit);
    };
    // Always resolves: "how did it end" is a question with four answers and no
    // failure mode, so forcing callers into try/catch would be noise.
    const settle = (outcome: WorkerOutcome): void => {
      if (settled) return;
      settled = true;
      cleanup();
      resolve(outcome);
    };

    const onMessage = (value: unknown): void => settle({ kind: "message", value });
    const onError = (error: Error): void => settle({ kind: "error", error });
    const onMessageError = (error: Error): void => settle({ kind: "messageerror", error });
    // Reached alone only for a silent exit: a throw emits "error" first, and
    // that event carries the stack this one does not have.
    const onExit = (code: number): void => settle({ kind: "exit", code });

    worker.on("message", onMessage);
    worker.on("error", onError);
    worker.on("messageerror", onMessageError);
    worker.on("exit", onExit);
  });
}

