  stdout: string;
  stderr: string;
}

export function runCommand(file: string, args: readonly string[]): Promise<CommandResult>
```

Spawn without a shell, collect both streams to completion, and resolve when
the child *and* its stdio are finished. Decode as UTF-8 only after you have
all the bytes. If the process cannot be started at all, reject with the
`error` event's error.

```ts
await runCommand(process.execPath, ["-e", "console.log('hi'); process.exit(2)"]);
// { code: 2, signal: null, stdout: "hi\n", stderr: "" }

await runCommand("definitely-not-a-real-binary", []);   // rejects, error.code === "ENOENT"
```

