## Problem 2 — lines, not chunks

Edit `ex2/solution.ts`. Implement:

```ts
export interface LineSplitter {
  push(chunk: string | Buffer): void;
  end(): void;
  readonly pending: string;
}

export function createLineSplitter(onLine: (line: string) => void): LineSplitter
```

Chunks arrive with arbitrary boundaries. Emit one call to `onLine` per
complete line, without the terminator, and hold whatever comes after the last
newline in `pending`. `end()` flushes a non-empty tail as a final line and
then leaves `pending` empty; calling `end()` twice emits nothing the second
time.

Handle `\r\n` as well as `\n` (strip the `\r`), and treat an empty line as a
line.

```ts
const seen: string[] = [];
const s = createLineSplitter((l) => seen.push(l));
s.push("hello\nwor");
s.push("ld\r\n\nlast");
s.end();
// seen === ["hello", "world", "", "last"]
```

```
uv run dojo test node v3nc02_child_processes ex2
```

references.solution.ts:
// v3nc02_child_processes / ex2 - reference solution (author only, used by `dojo verify`).

export interface LineSplitter {
  push(chunk: string | Buffer): void;
  end(): void;
  readonly pending: string;
}

export function createLineSplitter(onLine: (line: string) => void): LineSplitter {
  // Everything received since the last newline. Not a line yet: the beginning
  // of one, or nothing.
  let pending = "";
  let ended = false;

  const emit = (part: string): void => {
    // Strip only a terminator CR, never a CR inside the line - progress bars
    // and carriage-return redraws are legitimate data.
    onLine(part.endsWith("\r") ? part.slice(0, -1) : part);
  };

  return {
    push(chunk: string | Buffer): void {
      if (ended) return;
      const parts = (pending + chunk.toString()).split("\n");
      // split always leaves the incomplete tail last, for every input.
      pending = parts.pop() ?? "";
      for (const part of parts) emit(part);
    },

    end(): void {
      if (ended) return;
      ended = true;
      const tail = pending;
      // Clear before the callback: a handler that pushes must not see the tail
      // it is currently being given.
      pending = "";
      if (tail.length > 0) emit(tail);
    },

    get pending(): string {
      return pending;
    },
  };
}

