references.solution.ts:
// v3nc02_child_processes / ex3 - reference solution (author only, used by `dojo verify`).
import { spawn } from "node:child_process";

export interface TimedResult {
  code: number | null;
  signal: NodeJS.Signals | null;
  stdout: string;
  timedOut: boolean;
  escalated: boolean;
}

export function runWithTimeout(
  file: string,
  args: readonly string[],
  options: { timeoutMs: number; graceMs?: number },
): Promise<TimedResult> {
  const graceMs = options.graceMs ?? 100;

  return new Promise<TimedResult>((resolve, reject) => {
    const child = spawn(file, [...args], { stdio: ["ignore", "pipe", "ignore"] });
    const out: Buffer[] = [];
    child.stdout.on("data", (chunk: Buffer) => out.push(chunk));

    let timedOut = false;
    let escalated = false;
    let grace: NodeJS.Timeout | undefined;

    const deadline = setTimeout(() => {
      timedOut = true;
      // Ask politely: SIGTERM is catchable, so the child may still flush and
      // clean up. On Windows there are no signals and this behaves like a kill.
      child.kill("SIGTERM");
      grace = setTimeout(() => {
        escalated = true;
        // SIGKILL cannot be caught, blocked or ignored. It is the last resort
        // precisely because it skips every cleanup the child wanted to do.
        child.kill("SIGKILL");
      }, graceMs);
      grace.unref?.();
    }, options.timeoutMs);
    deadline.unref?.();

    const clear = (): void => {
      clearTimeout(deadline);
      if (grace) clearTimeout(grace);
    };

    child.once("error", (error) => {
      clear();
      reject(error);
    });

    child.once("close", (code, signal) => {
      clear();
      resolve({
        code,
        signal,
        stdout: Buffer.concat(out).toString("utf8"),
        timedOut,
        escalated,
      });
    });
  });
}

