## Challenge — a small job runner

Edit `challenge/solution.ts`. Build the thing the previous exercises were
parts of:

```ts
export interface Job { id: string; file: string; args: readonly string[]; }
export interface JobReport {
  id: string;
  lines: string[];
  code: number | null;
  timedOut: boolean;
  escalated: boolean;
  error?: string;
}

export function createRunner(options: {
  concurrency: number;
  timeoutMs: number;
  graceMs?: number;
  onLine?: (id: string, line: string) => void;
}): {
  run(jobs: readonly Job[]): Promise<JobReport[]>;
