// v3nc02_child_processes / challenge - reference solution (author only, used by `dojo verify`).
import { spawn } from "node:child_process";

export interface Job {
  id: string;
  file: string;
  args: readonly string[];
}

export interface JobReport {
  id: string;
  lines: string[];
  code: number | null;
  timedOut: boolean;
  escalated: boolean;
  error?: string;
}

function splitter(onLine: (line: string) => void): { push(s: string): void; end(): void } {
  let pending = "";
  let ended = false;
  const emit = (part: string): void => onLine(part.endsWith("\r") ? part.slice(0, -1) : part);
  return {
    push(text: string): void {
      const parts = (pending + text).split("\n");
      pending = parts.pop() ?? "";
      for (const part of parts) emit(part);
    },
    end(): void {
      if (ended) return;
      ended = true;
      const tail = pending;
      pending = "";
      if (tail.length > 0) emit(tail);
    },
  };
}

export function createRunner(options: {
  concurrency: number;
  timeoutMs: number;
  graceMs?: number;
  onLine?: (id: string, line: string) => void;
}) {
  const graceMs = options.graceMs ?? 100;
  let running = 0;

  function runJob(job: Job): Promise<JobReport> {
    return new Promise<JobReport>((resolve) => {
      const lines: string[] = [];
      const split = splitter((line) => {
        lines.push(line);
        // Caller code inside our data handler: a throw here would surface as
        // an uncaught exception from a stream emit, so it is contained.
        try {
          options.onLine?.(job.id, line);
        } catch {
          /* a broken consumer must not kill the batch */
        }
      });

      let timedOut = false;
      let escalated = false;
      let grace: NodeJS.Timeout | undefined;
      let settled = false;
      running += 1;

      const finish = (report: Omit<JobReport, "id" | "lines">): void => {
        if (settled) return;
        settled = true;
        running -= 1;
        clearTimeout(deadline);
        if (grace) clearTimeout(grace);
        // Flush driven by the stream ending, not by the clock: the last
        // partial line of a killed child was delivered before close.
        split.end();
        resolve({ id: job.id, lines, ...report });
      };

      const child = spawn(job.file, [...job.args], { stdio: ["ignore", "pipe", "ignore"] });
      child.stdout.setEncoding("utf8");
      child.stdout.on("data", (text: string) => split.push(text));

      const deadline = setTimeout(() => {
        timedOut = true;
        child.kill("SIGTERM");
        grace = setTimeout(() => {
          escalated = true;
          child.kill("SIGKILL");
        }, graceMs);
        grace.unref?.();
      }, options.timeoutMs);
      deadline.unref?.();

      child.once("error", (error) =>
        finish({ code: null, timedOut, escalated, error: error.message }),
      );
      child.once("close", (code) => finish({ code, timedOut, escalated }));
    });
  }

  return {
    async run(jobs: readonly Job[]): Promise<JobReport[]> {
      if (!Number.isInteger(options.concurrency) || options.concurrency < 1) {
        throw new RangeError("concurrency must be a positive integer");
      }
      const reports = new Array<JobReport>(jobs.length);
      let next = 0;
      const lane = async (): Promise<void> => {
        while (next < jobs.length) {
          const index = next++;
          reports[index] = await runJob(jobs[index]);
        }
      };
      const lanes = Math.min(options.concurrency, jobs.length);
      await Promise.all(Array.from({ length: lanes }, lane));
      return reports;
    },

    active(): number {
      return running;
    },
  };
}

