// v3nc02_child_processes / review1 - reference solution (author only, used by `dojo verify`).
import { spawn } from "node:child_process";

export interface CaptureResult {
  stdout: string;
  truncated: boolean;
  code: number | null;
}

export function execCapture(
  file: string,
  args: readonly string[],
  options: { maxBuffer?: number } = {},
): Promise<CaptureResult> {
  // Bytes, like Node's own maxBuffer - string.length would make the limit vary
  // with the content's encoding.
  const maxBuffer = options.maxBuffer ?? 1024;

  return new Promise<CaptureResult>((resolve, reject) => {
    const child = spawn(file, [...args], { stdio: ["ignore", "pipe", "ignore"] });

    const kept: Buffer[] = [];
    let total = 0;
    let truncated = false;

    child.stdout.on("data", (chunk: Buffer) => {
      if (truncated) return;
      if (total + chunk.length <= maxBuffer) {
        kept.push(chunk);
        total += chunk.length;
        return;
      }
      // Keep exactly the room that is left, copying so the whole 64 KB chunk
      // is not retained for the sake of ten bytes.
      const room = maxBuffer - total;
      if (room > 0) kept.push(Buffer.from(chunk.subarray(0, room)));
      total = maxBuffer;
      truncated = true;
      child.kill("SIGTERM");
      // Keep draining so the child cannot block on a full pipe while it dies.
      child.stdout.resume();
    });

    child.once("error", reject);
    // A killed child reports code null and a signal; saying 0 here would be a
    // lie the caller cannot detect.
    child.once("close", (code) =>
      resolve({ stdout: Buffer.concat(kept).toString("utf8"), truncated, code }),
    );
  });
}

