// v3nc03_cluster_scaling / ex3 - reference solution (author only, used by `dojo verify`).

export interface StickyRouter {
  route(key: string): string | undefined;
  remove(id: string): void;
  add(id: string): void;
}

// FNV-1a, 32 bits. Math.imul is the 32-bit multiply; plain `*` would spill
// into floating point and lose exactly the low bits the hash depends on.
export function hashKey(key: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < key.length; i++) {
    h ^= key.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

export function createStickyRouter(ids: readonly string[]): StickyRouter {
  const workers = new Set(ids);

  return {
    route(key: string): string | undefined {
      let best: string | undefined;
      let bestWeight = -1;
      for (const id of workers) {
        // Highest random weight: each worker scores the key independently, so
        // removing one worker cannot change any other worker's score.
        const weight = hashKey(`${key}|${id}`);
        if (weight > bestWeight || (weight === bestWeight && best !== undefined && id > best)) {
          best = id;
          bestWeight = weight;
        }
      }
      return best;
    },

    remove(id: string): void {
      workers.delete(id);
    },

    add(id: string): void {
      workers.add(id);
    },
  };
}

// v3nc03_cluster_scaling / ex4 - reference solution (author only, used by `dojo verify`).
import { spawn, type ChildProcess } from "node:child_process";

export interface WorkerHandle {
  id: number;
  pid: number;
  send(value: unknown): void;
}

export interface Fleet {
  workers(): WorkerHandle[];
  shutdown(): Promise<number[]>;
}

export async function startWorkers(count: number, source: string): Promise<Fleet> {
  const children: ChildProcess[] = [];

  try {
    const ready = Array.from({ length: count }, () => {
      const child = spawn(process.execPath, ["-e", source], {
        stdio: ["ignore", "ignore", "ignore", "ipc"],
      });
      children.push(child);

      return new Promise<void>((resolve, reject) => {
        // Spawned is not ready: the process exists long before it has loaded
        // its modules and bound anything.
        const onMessage = (message: { type?: string }): void => {
          if (message?.type === "ready") {
            child.off("message", onMessage);
            resolve();
          }
        };
        child.on("message", onMessage);
        child.once("error", reject);
        // Without this, a worker that dies during startup makes the whole
        // deploy hang with no error anywhere.
        child.once("exit", (code, signal) =>
          reject(new Error(`worker exited (code=${code}, signal=${signal}) before reporting ready`)),
        );
      });
    });

    await Promise.all(ready);
  } catch (error) {
    // Promise.all rejects on the first failure and cancels nothing.
    for (const child of children) child.kill("SIGKILL");
    throw error;
  }

  return {
    workers(): WorkerHandle[] {
      return children.map((child, id) => ({
        id,
        pid: child.pid ?? -1,
        send: (value: unknown) => {
          if (child.connected) child.send(value);
        },
      }));
    },

    shutdown(): Promise<number[]> {
      return Promise.all(
        children.map(
          (child) =>
            new Promise<number>((resolve) => {
              if (child.exitCode !== null) return resolve(child.exitCode);
              child.once("exit", (code) => resolve(code ?? -1));
              // Closing the channel is enough for an idle child: it was the
              // handle keeping its event loop alive.
              if (child.connected) child.disconnect();
              else child.kill("SIGTERM");
            }),
        ),
      );
    },
  };
}

