// v3nc03_cluster_scaling / ex5 - reference solution (author only, used by `dojo verify`).

export interface RestartDecision {
  action: "restart" | "give-up";
  delayMs: number;
  crashesInWindow: number;
}

export function createRestartPolicy(options: {
  baseMs: number;
  maxMs: number;
  windowMs: number;
  maxCrashesInWindow: number;
  now: () => number;
  random: () => number;
}): { onCrash(deliberate: boolean): RestartDecision; reset(): void } {
  const crashes: number[] = [];

  return {
    onCrash(deliberate: boolean): RestartDecision {
      // A worker we asked to stop is not evidence of anything being wrong;
      // counting it would let a rolling restart trip the crash budget.
      if (deliberate) {
        return { action: "restart", delayMs: 0, crashesInWindow: crashes.length };
      }

      const now = options.now();
      crashes.push(now);
      // Prune at write time so "N crashes in the window" means the window,
      // not "the last N crashes whenever they happened".
      const cutoff = now - options.windowMs;
      while (crashes.length > 0 && crashes[0] < cutoff) crashes.shift();

      if (crashes.length > options.maxCrashesInWindow) {
        // Hand the decision up: a supervisor that retries forever hides a
        // broken deploy behind a process that is technically running.
        return { action: "give-up", delayMs: 0, crashesInWindow: crashes.length };
      }

      const exponential = options.baseMs * 2 ** (crashes.length - 1);
      const capped = Math.min(options.maxMs, exponential);
      // Multiplicative jitter: twenty instances that crashed together must not
      // retry together for ever.
      const delayMs = Math.floor(capped * (0.5 + options.random() * 0.5));

      return { action: "restart", delayMs, crashesInWindow: crashes.length };
    },

    // Call once a worker has stayed up long enough to prove the deploy works.
    reset(): void {
      crashes.length = 0;
    },
  };
}

// v3nc03_cluster_scaling / ex6 - reference solution (author only, used by `dojo verify`).

export interface FleetController {
  ids(): string[];
  start(): Promise<string>;
  stop(id: string): Promise<void>;
  healthyCount(): number;
}

export async function rollingRestart(
  controller: FleetController,
  options: { minHealthy: number },
): Promise<string[]> {
  // Snapshot first: iterating a live list would restart our own replacements.
  const original = controller.ids();
  const created: string[] = [];

  for (const old of original) {
    // Up before down, always. The reverse order dips below minHealthy for as
    // long as a worker takes to become ready - during a deploy, under load.
    created.push(await controller.start());

    if (controller.healthyCount() < options.minHealthy) {
      throw new Error(
        `fleet fell below minHealthy (${controller.healthyCount()} < ${options.minHealthy}) after starting a worker`,
      );
    }

    await controller.stop(old);
  }

  return created;
  // Note on the failure path: if start() rejects, this function throws with
  // the remaining old workers untouched. A mixed fleet is serving; a fleet
  // torn down because the deploy failed is an outage.
}

