## Challenge — the controller

Edit `challenge/solution.ts`. Build the supervisor the sector has been
assembling:

```ts
export interface Effects {
  spawn(): Promise<{ id: string }>;          // resolves when the worker is ready
  stop(id: string): Promise<void>;           // graceful disconnect + drain
  kill(id: string): void;                    // forced
  now(): number;
  random(): number;
  setTimer(fn: () => void, ms: number): { cancel(): void };
}

export interface Controller {
  start(size: number): Promise<void>;
  onExit(id: string, deliberate: boolean): void;
  rollingRestart(): Promise<void>;
  shutdown(): Promise<void>;
  state(): { workers: string[]; givenUp: boolean; restarts: number };
}

export function createClusterController(options: {
  effects: Effects;
  baseMs: number;
  maxMs: number;
  windowMs: number;
  maxCrashesInWindow: number;
}): Controller
```

Behaviour:

- `start(size)` spawns `size` workers and records them;
- `onExit(id, deliberate)` removes the worker; a deliberate exit is not a
  crash; a crash schedules a replacement after the ex5 backoff, or sets
  `givenUp` and spawns nothing once the budget is exceeded;
- `rollingRestart()` replaces every current worker one at a time, never
  dropping below the original size;
- `shutdown()` cancels any pending restart timer and stops every worker;
- after `shutdown()`, a crash does not schedule anything.

Every effect is injected, so the gate drives the whole controller without
spawning a single process.

```
uv run dojo test node v3nc03_cluster_scaling challenge
```

references.solution.ts:
// v3nc03_cluster_scaling / challenge - reference solution (author only, used by `dojo verify`).

export interface Effects {
  spawn(): Promise<{ id: string }>;
  stop(id: string): Promise<void>;
  kill(id: string): void;
  now(): number;
  random(): number;
  setTimer(fn: () => void, ms: number): { cancel(): void };
}

export interface Controller {
  start(size: number): Promise<void>;
  onExit(id: string, deliberate: boolean): void;
  rollingRestart(): Promise<void>;
  shutdown(): Promise<void>;
  state(): { workers: string[]; givenUp: boolean; restarts: number };
}

export function createClusterController(options: {
  effects: Effects;
  baseMs: number;
  maxMs: number;
  windowMs: number;
  maxCrashesInWindow: number;
}): Controller {
  const { effects } = options;
  const workers: string[] = [];
  const crashes: number[] = [];
  const timers = new Set<{ cancel(): void }>();
  let givenUp = false;
  let restarts = 0;
  let shuttingDown = false;

  const later = (fn: () => void, ms: number): void => {
    const timer = effects.setTimer(() => {
      // Remove on fire, or the set grows for the life of the process.
      timers.delete(timer);
      fn();
    }, ms);
    timers.add(timer);
  };

  const backoffFor = (count: number): number => {
    const capped = Math.min(options.maxMs, options.baseMs * 2 ** (count - 1));
    return Math.floor(capped * (0.5 + effects.random() * 0.5));
  };

  return {
    async start(size: number): Promise<void> {
      for (let i = 0; i < size; i++) {
        const worker = await effects.spawn();
        workers.push(worker.id);
      }
    },

    onExit(id: string, deliberate: boolean): void {
      const index = workers.indexOf(id);
      if (index >= 0) workers.splice(index, 1);
      // A worker we asked to stop is not evidence of a broken deploy.
      if (deliberate || shuttingDown || givenUp) return;

      const now = effects.now();
      crashes.push(now);
      const cutoff = now - options.windowMs;
      while (crashes.length > 0 && crashes[0] < cutoff) crashes.shift();

      if (crashes.length > options.maxCrashesInWindow) {
        // Stop replacing - but leave the survivors serving. Giving up is not a
        // reason to turn a degraded fleet into a dead one.
        givenUp = true;
        return;
      }

      later(() => {
        // A timer scheduled before shutdown still fires after it.
        if (shuttingDown || givenUp) return;
        restarts += 1;
        void effects.spawn().then((worker) => {
          if (shuttingDown) return void effects.kill(worker.id);
          workers.push(worker.id);
        });
      }, backoffFor(crashes.length));
    },

    async rollingRestart(): Promise<void> {
      const original = [...workers];
      for (const old of original) {
        if (shuttingDown) return;
        // Up before down: the fleet goes n -> n+1 -> n, never n -> n-1.
        const replacement = await effects.spawn();
        workers.push(replacement.id);
        await effects.stop(old);
        const index = workers.indexOf(old);
        if (index >= 0) workers.splice(index, 1);
      }
    },

    async shutdown(): Promise<void> {
      shuttingDown = true;
      for (const timer of timers) timer.cancel();
      timers.clear();
      const all = [...workers];
      workers.length = 0;
      await Promise.all(all.map((id) => effects.stop(id)));
    },

    state() {
      return { workers: [...workers], givenUp, restarts };
    },
  };
}

// v3nc03_cluster_scaling / review1 - reference solution (author only, used by `dojo verify`).

export interface WorkerReport {
  workerId: string;
  counts: Record<string, number>;
}

export interface MergeResult {
  totals: Record<string, number>;
  overLimit: string[];
  falseAllows: Record<string, number>;
}

export function mergeWindows(reports: readonly WorkerReport[], limit: number): MergeResult {
  const totals: Record<string, number> = {};
  for (const report of reports) {
    for (const [key, count] of Object.entries(report.counts)) {
      totals[key] = (totals[key] ?? 0) + count;
    }
  }

  const overLimit: string[] = [];
  const falseAllows: Record<string, number> = {};
  for (const [key, total] of Object.entries(totals)) {
    if (total <= limit) continue;
    overLimit.push(key);
    // The size of the hole per-process state left in a limit we believed we
    // were enforcing: requests served that one shared counter would have
    // rejected.
    falseAllows[key] = total - limit;
  }

  // Sorted, because a report whose order changes when nothing changed is a
  // report nobody trusts.
  overLimit.sort();

  return { totals, overLimit, falseAllows };
}

