`type` is an index too, into `meta.node_types[0]` — an array of type names
like `"hidden"`, `"array"`, `"string"`, `"object"`, `"closure"`.

## Hint 3

The prefix sum is one accumulator in the same loop:

```ts
let firstEdge = 0;
for (let k = 0; k < nodeCount; k++) {
  // ... read fields ...
  result.push({ ..., firstEdge });
  firstEdge += edgeCount;
}
```

The decision left to you: whether to keep `edges` as the raw flat array or
decode it too. Decoding every edge eagerly doubles your memory for a file that
is already enormous — think about who needs it and when.

references.solution.ts:
// v3nc04_memory_leaks / ex2 - reference solution (author only, used by `dojo verify`).

export interface HeapNode {
  index: number;
  id: number;
  type: string;
  name: string;
  selfSize: number;
  edgeCount: number;
  firstEdge: number;
}

export interface ParsedSnapshot {
  nodes: HeapNode[];
  edgeFieldCount: number;
  edges: number[];
  strings: string[];
}

export function parseSnapshot(json: string): ParsedSnapshot {
  const raw = JSON.parse(json) as {
    snapshot: { meta: { node_fields: string[]; node_types: unknown[]; edge_fields: string[] } };
    nodes: number[];
    edges: number[];
    strings: string[];
  };

  const fields = raw.snapshot.meta.node_fields;
  const stride = fields.length;
  // Read the column positions from meta: the field list has gained columns
  // between V8 versions, and hard-coded offsets silently decode garbage.
  const typeIdx = fields.indexOf("type");
  const nameIdx = fields.indexOf("name");
  const idIdx = fields.indexOf("id");
  const sizeIdx = fields.indexOf("self_size");
  const edgeCountIdx = fields.indexOf("edge_count");
  const nodeTypes = (raw.snapshot.meta.node_types[0] as string[]) ?? [];

  const nodes: HeapNode[] = [];
  const count = Math.floor(raw.nodes.length / stride);
  // Each node's edges are the next edge_count records, so "where do node k's
  // edges start" is the running total of everything before it.
  let firstEdge = 0;

  for (let k = 0; k < count; k++) {
    const base = k * stride;
    const edgeCount = raw.nodes[base + edgeCountIdx];
    nodes.push({
      index: k,
      id: raw.nodes[base + idIdx],
      type: nodeTypes[raw.nodes[base + typeIdx]] ?? "unknown",
      name: raw.strings[raw.nodes[base + nameIdx]] ?? "",
      selfSize: raw.nodes[base + sizeIdx],
      edgeCount,
      firstEdge,
    });
    firstEdge += edgeCount;
  }

  return {
    nodes,
    edgeFieldCount: raw.snapshot.meta.edge_fields.length,
    // Left flat on purpose: an object per edge would multiply the memory cost
    // of a file that is already larger than the heap it describes.
    edges: raw.edges,
    strings: raw.strings,
  };
}

exercises.hints:
## Hint 1

A `Map` from name to a running total, one pass, then sort. The interesting
decisions are all in the filtering and the tie-break, not the aggregation.

## Hint 2

```ts
const totals = new Map<string, ConstructorTotal>();
for (const node of snapshot.nodes) {
  if (!allowed.has(node.type)) continue;
  const entry = totals.get(node.name) ?? { name: node.name, count: 0, selfSize: 0 };
  entry.count += 1;
  entry.selfSize += node.selfSize;
  totals.set(node.name, entry);
}
```

Mutating the entry you just read avoids a second `set` per node, which
matters when `nodes` has three million elements.

## Hint 3

Sort with an explicit tie-break:

```ts
list.sort((a, b) => b.selfSize - a.selfSize || a.name.localeCompare(b.name));
```

Without the second clause the order of equal-sized entries depends on
insertion, which makes your report change between runs on identical input.

The decision left to you: whether `selfSize` is even the right thing to rank
by. It is not, really — retained size is — and knowing why you are using the
available approximation is part of the exercise.

references.solution.ts:
// v3nc04_memory_leaks / ex3 - reference solution (author only, used by `dojo verify`).

export interface ConstructorTotal {
  name: string;
  count: number;
  selfSize: number;
}

export function bytesByConstructor(
  snapshot: { nodes: Array<{ name: string; type: string; selfSize: number }> },
  options: { top?: number; types?: readonly string[] } = {},
): ConstructorTotal[] {
  // Without the filter every snapshot answers "(string)", "(array)",
  // "(system)" - all true, none of it naming a line in your codebase.
  const allowed = new Set(options.types ?? ["object", "closure"]);
  const totals = new Map<string, ConstructorTotal>();

  for (const node of snapshot.nodes) {
    if (!allowed.has(node.type)) continue;
    const entry = totals.get(node.name);
    if (entry) {
      // Mutating the entry avoids a second Map.set per node, which is worth
      // caring about at three million nodes.
      entry.count += 1;
      entry.selfSize += node.selfSize;
    } else {
      totals.set(node.name, { name: node.name, count: 1, selfSize: node.selfSize });
    }
  }

  return [...totals.values()]
    // Self size, not retained size: this is the cheap approximation, and it
    // finds the contents of a leak rather than the container holding them.
    .sort((a, b) => b.selfSize - a.selfSize || a.name.localeCompare(b.name))
    .slice(0, options.top ?? 10);
}

// v3nc04_memory_leaks / ex4 - reference solution (author only, used by `dojo verify`).

export interface Graph {
  nodes: Array<{ index: number; id: number; name: string; edgeCount: number; firstEdge: number }>;
  edges: Array<{ toNode: number; name: string }>;
}

export function retainerPath(graph: Graph, targetId: number): string[] | undefined {
  const target = graph.nodes.findIndex((node) => node.id === targetId);
  if (target < 0) return undefined;
  if (target === 0) return [graph.nodes[0].name];

  // BFS, not DFS: the shortest path is the one that names the variable
  // actually responsible, rather than a long route through unrelated objects.
  const parent = new Map<number, { from: number; edge: string }>();
  const seen = new Set<number>([0]);
  const queue: number[] = [0];
  // An index cursor rather than shift(): shift() is O(n) per call, and heap
  // graphs have millions of nodes.
  let head = 0;

  while (head < queue.length) {
    const current = queue[head++];
    const node = graph.nodes[current];
    for (let e = node.firstEdge; e < node.firstEdge + node.edgeCount; e++) {
      const edge = graph.edges[e];
      if (!edge) continue;
      // Heap graphs are full of cycles; the seen set is what terminates.
      if (seen.has(edge.toNode)) continue;
      seen.add(edge.toNode);
      parent.set(edge.toNode, { from: current, edge: edge.name });
      if (edge.toNode === target) {
        const path: string[] = [];
        let at = target;
        while (at !== 0) {
          const step = parent.get(at);
          if (!step) return undefined;
          path.push(graph.nodes[at].name, step.edge);
          at = step.from;
        }
        path.push(graph.nodes[0].name);
        return path.reverse();
      }
      queue.push(edge.toNode);
    }
  }

  return undefined;
}

