export interface Totals { name: string; count: number; selfSize: number; }
export interface Growth {
  name: string;
  countDelta: number;
  bytesDelta: number;
  ratio: number;         // after.selfSize / before.selfSize, Infinity when before was 0
}

export function diffSnapshots(
  before: readonly Totals[],
  after: readonly Totals[],
  options?: { minBytes?: number; minRatio?: number },
): Growth[]
