references.solution.ts:
// v3nc04_memory_leaks / ex6 - reference solution (author only, used by `dojo verify`).

export interface LruCache<V> {
  get(key: string): V | undefined;
  set(key: string, value: V): void;
  delete(key: string): boolean;
  readonly size: number;
  readonly bytes: number;
}

export function createLruCache<V>(options: {
  maxBytes: number;
  sizeOf: (value: V) => number;
}): LruCache<V> {
  // Map iterates in insertion order, so delete-then-set is a move-to-end and
  // the first key is always the least recently used. No linked list needed.
  const store = new Map<string, V>();
  const sizes = new Map<string, number>();
  let bytes = 0;

  const drop = (key: string): void => {
    const size = sizes.get(key);
    if (size === undefined) return;
    bytes -= size;
    sizes.delete(key);
    store.delete(key);
  };

  return {
    get(key: string): V | undefined {
      if (!store.has(key)) return undefined;
      const value = store.get(key) as V;
      // A read is a use: re-inserting moves the key to the recent end.
      store.delete(key);
      store.set(key, value);
      return value;
    },

    set(key: string, value: V): void {
      // sizeOf once per set: calling it repeatedly assumes purity and a value
      // nobody mutates after insertion.
      const size = options.sizeOf(value);

      // Before any eviction: otherwise we empty the cache to make room for
      // something we then refuse to store.
      if (size > options.maxBytes) {
        drop(key);
        return;
      }

      // Subtract the old size on overwrite, or `bytes` drifts permanently
      // above the truth and the cache evicts everything for ever.
      drop(key);
      store.set(key, value);
      sizes.set(key, size);
      bytes += size;

      // While, not if: one large insert can displace several small entries.
      while (bytes > options.maxBytes) {
        const oldest = store.keys().next().value as string | undefined;
        if (oldest === undefined) break;
        drop(oldest);
      }
    },

    delete(key: string): boolean {
      const had = store.has(key);
      drop(key);
      return had;
    },

    get size(): number {
      return store.size;
    },

    get bytes(): number {
      return bytes;
    },
  };
}

