```

references.solution.ts:
// v3nc04_memory_leaks / ex7 - reference solution (author only, used by `dojo verify`).

export interface Registry<T> {
  subscribe(subscriber: object, handler: (event: T) => void, meta?: unknown): () => void;
  publish(event: T): number;
  metaFor(subscriber: object): unknown;
  readonly size: number;
}

interface Entry<T> {
  subscriber: object;
  handler: (event: T) => void;
}

export function createRegistry<T>(): Registry<T> {
  const entries = new Set<Entry<T>>();
  // Keyed by the subscriber, so the metadata's lifetime follows the
  // subscriber's. Note this makes the KEY weak, never the value: a WeakMap
  // whose values point back at their keys retains everything.
  const meta = new WeakMap<object, unknown>();

  return {
    subscribe(subscriber: object, handler: (event: T) => void, value?: unknown): () => void {
      // A distinct entry object per subscription: the same subscriber may
      // subscribe twice and unsubscribe each one independently.
      const entry: Entry<T> = { subscriber, handler };
      entries.add(entry);
      if (value !== undefined) meta.set(subscriber, value);
      // Idempotent for free: deleting something already gone is a no-op.
      return () => {
        entries.delete(entry);
      };
    },

    publish(event: T): number {
      let ran = 0;
      // Iterate a copy: a handler that unsubscribes during dispatch would
      // otherwise silently stop the handlers after it from running.
      for (const entry of [...entries]) {
        if (!entries.has(entry)) continue;
        ran += 1;
        try {
          entry.handler(event);
        } catch {
          // One broken subscriber must not deny the event to the others; a
          // real registry would report this to an error channel.
        }
      }
      return ran;
    },

    metaFor(subscriber: object): unknown {
      return meta.get(subscriber);
    },

    get size(): number {
      return entries.size;
    },
  };
}

