// v3nc04_memory_leaks / ex8 - reference solution (author only, used by `dojo verify`).

export type Trend = "stable" | "sawtooth" | "growing" | "insufficient-data";

export function classifyTrend(
  samples: readonly number[],
  options: { windowSize?: number; growthThreshold?: number } = {},
): { trend: Trend; minima: number[]; slopePerWindow: number } {
  const windowSize = options.windowSize ?? 5;

  // Minima, not raw samples: a reading taken mid-allocation includes garbage
  // that has not been collected yet, and only the live set matters.
  const minima: number[] = [];
  for (let start = 0; start + windowSize <= samples.length; start += windowSize) {
    // Complete windows only - a short final window is systematically higher
    // and tilts the slope upward into a leak that is not there.
    minima.push(Math.min(...samples.slice(start, start + windowSize)));
  }

  if (minima.length < 3) return { trend: "insufficient-data", minima, slopePerWindow: 0 };

  const n = minima.length;
  let sumX = 0;
  let sumY = 0;
  let sumXY = 0;
  let sumXX = 0;
  for (let i = 0; i < n; i++) {
    sumX += i;
    sumY += minima[i];
    sumXY += i * minima[i];
    sumXX += i * i;
  }
  const denominator = n * sumXX - sumX * sumX;
  // Guard the NaN: every NaN comparison is false, which would silently report
  // a leaking process as stable.
  const slopePerWindow = denominator === 0 ? 0 : (n * sumXY - sumX * sumY) / denominator;

  const threshold = options.growthThreshold ?? Math.abs(minima[0]) * 0.01;
  if (slopePerWindow > threshold) return { trend: "growing", minima, slopePerWindow };

  const low = Math.min(...samples);
  const high = Math.max(...samples);
  // Peaks that move while the minima do not: allocation and collection, which
  // is exactly what a healthy heap looks like.
  const trend: Trend = high - low > Math.abs(low) * 0.1 ? "sawtooth" : "stable";
  return { trend, minima, slopePerWindow };
}

