references.solution.ts:
// v3nc05_cpu_profiling / ex1 - reference solution (author only, used by `dojo verify`).
import { Session } from "node:inspector/promises";
import { performance } from "node:perf_hooks";

export interface ProfileRun<T> {
  result: T;
  durationMs: number;
  sampleCount: number;
  profile: unknown;
}

// Note: the profiler is a property of the isolate, not of this call. A real
// service needs a mutex around it - a second Profiler.start while one is
// running is an error, and a second stop ends the first caller's profile.
export async function profileFunction<T>(
  fn: () => T,
  options: { intervalUs?: number } = {},
): Promise<ProfileRun<T>> {
  const session = new Session();
  session.connect();

  try {
    await session.post("Profiler.enable");
    if (options.intervalUs !== undefined) {
      // Before start, not after: the interval is read when profiling begins.
      await session.post("Profiler.setSamplingInterval", { interval: options.intervalUs });
    }
    await session.post("Profiler.start");

    // Monotonic and sub-microsecond; Date.now() would round most runs to zero.
    const started = performance.now();
    let result: T;
    let failure: unknown;
    try {
      result = fn();
    } catch (error) {
      failure = error;
      result = undefined as T;
    }
    const durationMs = performance.now() - started;

    // Stop even on the failure path: the profiler is process-wide, and leaving
    // it running distorts every later measurement.
    const { profile } = (await session.post("Profiler.stop")) as {
      profile: { samples?: number[] };
    };
    if (failure) throw failure;

    return { result, durationMs, sampleCount: profile.samples?.length ?? 0, profile };
  } finally {
    // An inspector session left open holds resources, and connect() will throw
    // the next time somebody tries.
    session.disconnect();
  }
}

