exercises.hints:
## Hint 1

You need subtree totals before you can compare children, so this is two
passes: compute every node's subtree hits once, then walk down choosing the
maximum.

Computing subtree hits inside the descent instead re-walks the same subtrees
repeatedly and turns a linear job into a quadratic one.

## Hint 2

Memoise the subtree sums with a post-order walk:

```ts
const subtree = new Map<number, number>();
const size = (id: number): number => {
  if (subtree.has(id)) return subtree.get(id)!;
  const node = byId.get(id)!;
  let total = node.hitCount ?? 0;
  for (const child of node.children ?? []) total += size(child);
  subtree.set(id, total);
  return total;
};
```

Then the descent is a loop, not a recursion.

## Hint 3

The stopping rule matters: descend only while some child's subtree is larger
than the current node's own hits. Otherwise the path runs all the way to a
leaf with two samples and tells you nothing about where the time is.

The decision left to you: how to break a tie between two equally heavy
children. Any deterministic rule is fine; a non-deterministic one makes the
output change between runs on the same input.

references.solution.ts:
// v3nc05_cpu_profiling / ex5 - reference solution (author only, used by `dojo verify`).

interface Node {
  id: number;
  callFrame: { functionName: string };
  hitCount?: number;
  children?: number[];
}

export interface HeaviestPath {
  frames: string[];
  hits: number;
  share: number;
  verdict: "hot-spot" | "diffuse";
}

export function heaviestPath(
  profile: { nodes: Node[] },
  options: { hotSpotShare?: number } = {},
): HeaviestPath {
  const byId = new Map(profile.nodes.map((node) => [node.id, node]));
  const childIds = new Set<number>();
  for (const node of profile.nodes) for (const child of node.children ?? []) childIds.add(child);
  const root = profile.nodes.find((node) => !childIds.has(node.id));
  if (!root) return { frames: [], hits: 0, share: 0, verdict: "diffuse" };

  // Memoised subtree sums: computing them during the descent instead would
  // re-walk the same subtrees and turn a linear job into a quadratic one.
  const subtree = new Map<number, number>();
  const size = (id: number): number => {
    const cached = subtree.get(id);
    if (cached !== undefined) return cached;
    const node = byId.get(id);
    if (!node) return 0;
    let total = node.hitCount ?? 0;
    for (const child of node.children ?? []) total += size(child);
    subtree.set(id, total);
    return total;
  };

  const totalHits = size(root.id);
  const frames: string[] = [];
  let current = root;
  let hits = totalHits;

  for (;;) {
    frames.push(current.callFrame.functionName === "" ? "(anonymous)" : current.callFrame.functionName);
    let best: Node | undefined;
    let bestSize = current.hitCount ?? 0;
    for (const childId of current.children ?? []) {
      const child = byId.get(childId);
      if (!child) continue;
      const childSize = size(childId);
      // Strictly greater, and deterministic: an equal-size tie keeps the first
      // child so the output does not change between runs on the same input.
      if (childSize > bestSize) {
        best = child;
        bestSize = childSize;
      }
    }
    // Stop when no child beats this node's own samples, or the path runs on to
    // a leaf with two hits and explains nothing.
    if (!best) break;
    current = best;
    hits = bestSize;
  }

  const share = totalHits > 0 ? hits / totalHits : 0;
  return {
    frames,
    hits,
    share,
    // One function to fix, or death by a thousand cuts - the two call for
    // completely different responses.
    verdict: share >= (options.hotSpotShare ?? 0.3) ? "hot-spot" : "diffuse",
  };
}

