## Problem 7 — a benchmark that warms up

Edit `ex7/solution.ts`. Implement:

```ts
export interface BenchmarkResult {
  samplesNs: number[];        // per-iteration nanoseconds, one entry per trial, sorted ascending
  medianNs: number;
  p95Ns: number;
  minNs: number;
  meanNs: number;
  trials: number;
  warmupIterations: number;
}

export function benchmark(
  fn: () => unknown,
  options?: { warmup?: number; trials?: number; iterations?: number },
): BenchmarkResult
```

Defaults: `warmup` 200, `trials` 30, `iterations` 1000.

- run `fn` `warmup` times and discard the results — you are letting V8 optimise
  the function so you measure the code that will actually run;
- then for each trial, time `iterations` calls with `process.hrtime.bigint()`
  and record the **per-iteration** nanoseconds;
- consume `fn`'s return value in a way the optimiser cannot remove, or a
  function whose result is unused can be eliminated entirely and you will
  measure nothing;
- report the median and p95 from the sorted samples using the
  nearest-rank rule: `sorted[Math.min(n - 1, Math.ceil(p * n) - 1)]`.

```ts
const r = benchmark(() => JSON.stringify({ a: 1 }));
r.medianNs > 0;             // true
r.samplesNs.length === 30;  // true
```

```
uv run dojo test node v3nc05_cpu_profiling ex7
```

references.solution.ts:
// v3nc05_cpu_profiling / ex7 - reference solution (author only, used by `dojo verify`).

export interface BenchmarkResult {
  samplesNs: number[];
  medianNs: number;
  p95Ns: number;
  minNs: number;
  meanNs: number;
  trials: number;
  warmupIterations: number;
}

// Module scope so the optimiser cannot prove the assignment is dead. Without
// something like this, V8 can eliminate a call whose result is unused and the
// benchmark reports picoseconds.
let sink: unknown;

function percentile(sorted: readonly number[], p: number): number {
  if (sorted.length === 0) return 0;
  // Nearest-rank: no interpolation, no surprises at small sample counts.
  return sorted[Math.min(sorted.length - 1, Math.ceil(p * sorted.length) - 1)];
}

export function benchmark(
  fn: () => unknown,
  options: { warmup?: number; trials?: number; iterations?: number } = {},
): BenchmarkResult {
  const warmup = options.warmup ?? 200;
  const trials = options.trials ?? 30;
  const iterations = options.iterations ?? 1000;

  // Let TurboFan optimise before we start counting, or the first trials
  // measure the interpreter rather than the code that will ship.
  for (let i = 0; i < warmup; i++) sink = fn();

  const samplesNs: number[] = [];
  for (let t = 0; t < trials; t++) {
    // Monotonic nanoseconds. Batching `iterations` calls per timing keeps the
    // clock's resolution far away from the quantity being measured.
    const start = process.hrtime.bigint();
    for (let i = 0; i < iterations; i++) sink = fn();
    samplesNs.push(Number(process.hrtime.bigint() - start) / iterations);
  }

  samplesNs.sort((a, b) => a - b);
  const meanNs = samplesNs.reduce((a, b) => a + b, 0) / samplesNs.length;

  return {
    samplesNs,
    // The median, not the mean: iteration times have a long right tail from GC
    // and scheduling, and the mean lives in the tail.
    medianNs: percentile(samplesNs, 0.5),
    p95Ns: percentile(samplesNs, 0.95),
    minNs: samplesNs[0] ?? 0,
    meanNs,
    trials,
    warmupIterations: warmup,
  };
}

