## Problem 8 — refusing to declare a winner

Edit `ex8/solution.ts`. Implement:

```ts
export interface Comparison {
  verdict: "faster" | "slower" | "inconclusive";
  ratio: number;                 // b.median / a.median
  percentChange: number;         // (b.median - a.median) / a.median * 100
  aInterval: [number, number];
  bInterval: [number, number];
}

export function compareBenchmarks(
  a: readonly number[],
  b: readonly number[],
  options?: { confidence?: number; minEffectPercent?: number },
): Comparison
```

`a` and `b` are per-iteration samples from ex7. For each set compute the mean
and the standard error (`stddev / sqrt(n)`, using the sample standard
deviation with `n - 1`), then the interval
`mean ± z * standardError` where `z` is 1.96 for the default confidence of
0.95 and 2.576 for 0.99.

- overlapping intervals → `"inconclusive"`;
- non-overlapping, but `|percentChange| < minEffectPercent` (default 1) →
  `"inconclusive"` as well: a difference too small to care about is not a
  result;
- otherwise `"faster"` when b's median is lower, `"slower"` when higher.

Fewer than two samples in either set is `"inconclusive"` with zeroed
intervals.

```ts
compareBenchmarks([100, 101, 99, 100], [70, 71, 69, 70]);
// { verdict: "faster", ratio: 0.7, percentChange: -30, ... }
```

```
uv run dojo test node v3nc05_cpu_profiling ex8
```

references.solution.ts:
// v3nc05_cpu_profiling / ex8 - reference solution (author only, used by `dojo verify`).

export interface Comparison {
  verdict: "faster" | "slower" | "inconclusive";
  ratio: number;
  percentChange: number;
  aInterval: [number, number];
  bInterval: [number, number];
}

function stats(xs: readonly number[], z: number): { mean: number; median: number; interval: [number, number] } {
  const n = xs.length;
  const mean = xs.reduce((sum, x) => sum + x, 0) / n;
  // Bessel's correction: dividing by n at 30 samples understates the spread by
  // about 3%, which tilts you toward claiming results you do not have.
  const variance = xs.reduce((sum, x) => sum + (x - mean) ** 2, 0) / Math.max(1, n - 1);
  const stderr = Math.sqrt(variance) / Math.sqrt(n);
  const sorted = [...xs].sort((a, b) => a - b);
  return {
    mean,
    median: sorted[Math.min(n - 1, Math.ceil(0.5 * n) - 1)],
    interval: [mean - z * stderr, mean + z * stderr],
  };
}

const overlaps = (a: [number, number], b: [number, number]): boolean => a[0] <= b[1] && b[0] <= a[1];

export function compareBenchmarks(
  a: readonly number[],
  b: readonly number[],
  options: { confidence?: number; minEffectPercent?: number } = {},
): Comparison {
  if (a.length < 2 || b.length < 2) {
    return { verdict: "inconclusive", ratio: 1, percentChange: 0, aInterval: [0, 0], bInterval: [0, 0] };
  }

  const z = (options.confidence ?? 0.95) >= 0.99 ? 2.576 : 1.96;
  const left = stats(a, z);
  const right = stats(b, z);

  // Medians for the reported effect (robust to the long right tail), means for
  // the intervals (that is what the standard error describes).
  const ratio = left.median === 0 ? 1 : right.median / left.median;
  const percentChange = left.median === 0 ? 0 : ((right.median - left.median) / left.median) * 100;

  const result: Comparison = {
    verdict: "inconclusive",
    ratio,
    percentChange,
    aInterval: left.interval,
    bInterval: right.interval,
  };

  // Overlapping intervals: the measurement does not support a claim. This
  // approximation errs toward "inconclusive", which is the safe direction for
  // an engineering decision.
  if (overlaps(left.interval, right.interval)) return result;

  // Statistical significance answers "is it real"; effect size answers "do I
  // care". A detectable 0.3% win is not worth more complicated code.
  if (Math.abs(percentChange) < (options.minEffectPercent ?? 1)) return result;

  result.verdict = right.median < left.median ? "faster" : "slower";
  return result;
}

