  selfShare: number;
  totalShare: number;
  callers: string[];          // the path from the root to this frame's heaviest occurrence
  category: "javascript" | "gc" | "native" | "idle";
  advice: string;
}

export interface Report {
  totalSamples: number;
  gcShare: number;
  idleShare: number;
  recommendations: Recommendation[];
  summary: string;
}

export function optimisationReport(
  profile: { nodes: Array<{ id: number; callFrame: { functionName: string; url: string; lineNumber: number }; hitCount?: number; children?: number[] }>; startTime: number; endTime: number },
  options?: { top?: number; minShare?: number },
): Report
```

Requirements:

- rank by self share, dropping anything below `minShare` (default 0.02);
- classify each frame: `(garbage collector)` → `gc`, `(idle)`/`(program)` →
  `idle`, a frame whose `url` is empty or starts with `node:` → `native`,
  anything else → `javascript`;
- `advice` differs by category — a JavaScript frame is a code change, a GC
  frame redirects to allocation, a native frame is a library decision, and an
  idle frame means you are not CPU-bound;
- `callers` is the root-to-frame path of that frame's heaviest node;
- `summary` is one sentence naming the dominant category and the top frame.

```
