references.solution.ts:
// v3nc06_observability / ex1 - reference solution (author only, used by `dojo verify`).

export type Level = "debug" | "info" | "warn" | "error";

export interface Logger {
  debug(fields: Record<string, unknown>): void;
  info(fields: Record<string, unknown>): void;
  warn(fields: Record<string, unknown>): void;
  error(fields: Record<string, unknown>): void;
  child(bound: Record<string, unknown>): Logger;
}

const RANK: Record<Level, number> = { debug: 10, info: 20, warn: 30, error: 40 };

export function createLogger(options: {
  level: Level;
  write: (line: string) => void;
  now: () => number;
  base?: Record<string, unknown>;
}): Logger {
  const base = options.base ?? {};
  const threshold = RANK[options.level];

  const emit = (level: Level, fields: Record<string, unknown>): void => {
    // Filter before building anything: serialising a line you are about to
    // throw away is the classic hand-rolled-logger performance bug.
    if (RANK[level] < threshold) return;

    // Insertion order is JSON.stringify's key order, so this literal is the
    // stable schema. Later spreads win, which is the "nearest wins" rule.
    const line = { time: options.now(), level, ...base, ...fields };
    try {
      options.write(JSON.stringify(line));
    } catch (error) {
      // A logger that throws takes down the code trying to report a problem,
      // at the worst possible moment. Circular objects and BigInt do this.
      options.write(
        JSON.stringify({
          time: options.now(),
          level: "error",
          msg: "log serialisation failed",
          reason: (error as Error).message,
        }),
      );
    }
  };

  return {
    debug: (fields) => emit("debug", fields),
    info: (fields) => emit("info", fields),
    warn: (fields) => emit("warn", fields),
    error: (fields) => emit("error", fields),
    // A closure over merged fields, not a subclass: arbitrarily deep chains
    // cost nothing at log time.
    child: (bound) => createLogger({ ...options, base: { ...base, ...bound } }),
  };
}

