references.solution.ts:
// v3nc06_observability / ex2 - reference solution (author only, used by `dojo verify`).

type Bag = Record<string, unknown>;

const isContainer = (value: unknown): value is Bag | unknown[] =>
  Array.isArray(value) || (typeof value === "object" && value !== null && !(value instanceof Date) && !Buffer.isBuffer(value));

const shallowCopy = (value: Bag | unknown[]): Bag | unknown[] =>
  Array.isArray(value) ? [...value] : { ...value };

export function createRedactor(
  paths: readonly string[],
  options: { mask?: string; remove?: boolean } = {},
): <T>(value: T) => T {
  const mask = options.mask ?? "[redacted]";
  const compiled = paths.map((path) => path.split("."));

  return <T>(value: T): T => {
    if (!isContainer(value)) return value;
    // Copy on the way down: containers we pass through are cloned, everything
    // else stays shared with the original. Deep-cloning a request body to mask
    // one field is the most expensive thing a logger can do.
    const root = shallowCopy(value as unknown as Bag);

    const apply = (node: Bag | unknown[], segments: string[]): void => {
      const [head, ...rest] = segments;
      const container = node as Bag;
      const keys = head === "*" ? Object.keys(container) : [head];

      for (const key of keys) {
        if (!(key in container)) continue;
        if (rest.length === 0) {
          if (options.remove) delete container[key];
          else container[key] = mask;
          continue;
        }
        const child = container[key];
        if (!isContainer(child)) continue;
        const copy = shallowCopy(child);
        container[key] = copy;
        apply(copy, rest);
      }
    };

    for (const segments of compiled) apply(root, segments);
    return root as unknown as T;
  };
}

