## Review — publishing without monkey-patching

Edit `review1/solution.ts`. Implement:

```ts
export interface Instrumented {
  publishStart(payload: { operation: string; requestId?: string }): void;
  publishEnd(payload: { operation: string; durationMs: number; error?: Error }): void;
  hasSubscribers(): boolean;
}

export function createChannelInstrumentation(namespace: string): Instrumented

export function subscribeToOperations(
  namespace: string,
  handlers: { onStart?(message: unknown): void; onEnd?(message: unknown): void },
): () => void
```

Use `node:diagnostics_channel`. Publish on `` `${namespace}:start` `` and
`` `${namespace}:end` ``.

- `hasSubscribers()` reports whether **either** channel has a subscriber, so a
  caller can skip building an expensive payload when nobody is listening;
- `subscribeToOperations` returns an unsubscribe function that removes both
  handlers;
- publishing with no subscribers must be safe and must not construct anything
  it does not need.

The point of the exercise: a library instrumented this way can be observed
without anyone wrapping or monkey-patching its functions.

```ts
const bus = createChannelInstrumentation("myorm");
const off = subscribeToOperations("myorm", { onEnd: (m) => spans.push(m) });
bus.publishStart({ operation: "query" });
bus.publishEnd({ operation: "query", durationMs: 4 });
off();
```

```
uv run dojo test node v3nc06_observability review1
```

references.solution.ts:
// v3nc06_observability / review1 - reference solution (author only, used by `dojo verify`).
import diagnostics_channel from "node:diagnostics_channel";

export interface Instrumented {
  publishStart(payload: { operation: string; requestId?: string }): void;
  publishEnd(payload: { operation: string; durationMs: number; error?: Error }): void;
  hasSubscribers(): boolean;
}

export function createChannelInstrumentation(namespace: string): Instrumented {
  // channel(name) is a singleton per name, which is how a publisher and a
  // subscriber in unrelated modules find each other with no shared import.
  const start = diagnostics_channel.channel(`${namespace}:start`);
  const end = diagnostics_channel.channel(`${namespace}:end`);

  return {
    publishStart(payload): void {
      // The guard goes around the payload, not just the publish: publishing to
      // an empty channel is nearly free, building the message is not.
      if (!start.hasSubscribers) return;
      start.publish(payload);
    },

    publishEnd(payload): void {
      if (!end.hasSubscribers) return;
      end.publish(payload);
    },

    hasSubscribers: () => start.hasSubscribers || end.hasSubscribers,
  };
}

export function subscribeToOperations(
  namespace: string,
  handlers: { onStart?(message: unknown): void; onEnd?(message: unknown): void },
): () => void {
  const start = diagnostics_channel.channel(`${namespace}:start`);
  const end = diagnostics_channel.channel(`${namespace}:end`);

  // Subscribers are called synchronously on the publisher's stack, so a slow
  // one slows the library and a throwing one propagates into it. Contain both.
  const onStart = (message: unknown): void => {
    try {
      handlers.onStart?.(message);
    } catch {
      /* an observer must not break the thing it observes */
    }
  };
  const onEnd = (message: unknown): void => {
    try {
      handlers.onEnd?.(message);
    } catch {
      /* ditto */
    }
  };

  start.subscribe(onStart);
  end.subscribe(onEnd);

  // Matched by identity, exactly like EventEmitter.off - which is why the
  // references are kept rather than re-created here.
  return () => {
    start.unsubscribe(onStart);
    end.unsubscribe(onEnd);
  };
}
